  const vh = innerHeight;
  for (let i = 0; i < pages.length - 1; i++) {
    const t = pages[i + 1].getBoundingClientRect().top;
    pages[i].style.setProperty("--cv", Math.min(1, Math.max(0, 1 - t / vh)).toFixed(3));
