/* scratch the gold foil to reveal the date */
const foil = $("foil"), fx = foil.getContext("2d");
let revealed = false, scratched = 0, lastPt = null, fw = 0, fh = 0, fdpr = 1;
function paintFoil(){
  if (revealed) return;
  const r = foil.getBoundingClientRect(); fdpr = Math.min(2, devicePixelRatio || 1);
  fw = Math.max(1, r.width); fh = Math.max(1, r.height);
  foil.width = fw * fdpr; foil.height = fh * fdpr; fx.setTransform(fdpr, 0, 0, fdpr, 0, 0);
  const g = fx.createLinearGradient(0, 0, fw, fh);
  g.addColorStop(0, "#A8823A"); g.addColorStop(.28, "#F3DE9E"); g.addColorStop(.5, "#C9A45C"); g.addColorStop(.72, "#F6E6B2"); g.addColorStop(1, "#9A7432");
  fx.globalCompositeOperation = "source-over"; fx.fillStyle = g; fx.fillRect(0, 0, fw, fh);
  for (let i = 0; i < fw * fh / 40; i++) { fx.fillStyle = "rgba(255,255,255," + (Math.random() * .22).toFixed(2) + ")"; fx.fillRect(Math.random() * fw, Math.random() * fh, 1, 1); fx.fillStyle = "rgba(90,60,20," + (Math.random() * .16).toFixed(2) + ")"; fx.fillRect(Math.random() * fw, Math.random() * fh, 1, 1); }
  fx.strokeStyle = "rgba(255,248,220,.7)"; fx.lineWidth = 1; fx.strokeRect(9.5, 9.5, fw - 19, fh - 19);
  fx.textAlign = "center"; fx.textBaseline = "middle";
  fx.fillStyle = "rgba(110,27,45,.85)"; fx.font = "600 " + Math.round(fw * .036) + "px Figtree, system-ui, sans-serif";
  fx.fillText("✦  SCRATCH TO REVEAL  ✦", fw / 2, fh / 2 - fh * .1);
  fx.fillStyle = "rgba(110,27,45,.9)"; fx.font = "italic 500 " + Math.round(fw * .075) + "px 'Cormorant Garamond', Georgia, serif";
  fx.fillText("our wedding date", fw / 2, fh / 2 + fh * .09);
  scratched = 0;
}
function scratchAt(x, y){
  fx.globalCompositeOperation = "destination-out"; fx.lineCap = "round"; fx.lineJoin = "round"; fx.lineWidth = Math.max(34, fw * .11);
  fx.beginPath(); if (lastPt) fx.moveTo(lastPt[0], lastPt[1]); else fx.moveTo(x - .1, y); fx.lineTo(x, y); fx.stroke();
  lastPt = [x, y];
  if (++scratched % 8 === 0) checkFoil();
}
function checkFoil(){
  const d = fx.getImageData(0, 0, foil.width, foil.height).data; let clear = 0, tot = 0;
  for (let i = 3; i < d.length; i += 4 * 24) { tot++; if (d[i] < 30) clear++; }
  if (clear / tot > .42) revealDate();
}
function revealDate(){
  if (revealed) return; revealed = true;
  foil.classList.add("gone"); $("s-hint").style.visibility = "hidden"; $("s-after").classList.add("on");
  ac(); [1046.5, 1318.5, 1568, 2093].forEach((f, i) => chime(f, .045, i * .09)); shower(46);
}
foil.addEventListener("pointerdown", e => { e.preventDefault(); foil.setPointerCapture(e.pointerId); lastPt = null; const r = foil.getBoundingClientRect(); scratchAt(e.clientX - r.left, e.clientY - r.top); if (Math.random() < .5) chime(2637 + Math.random() * 400, .012, 0, [[1, 1, .15]]); });
foil.addEventListener("pointermove", e => { if (!foil.hasPointerCapture(e.pointerId)) return; const r = foil.getBoundingClientRect(); scratchAt(e.clientX - r.left, e.clientY - r.top); });
foil.addEventListener("pointerup", () => { lastPt = null; checkFoil(); });
$("s-btn").addEventListener("click", revealDate);
let lastFw = 0;
function sizeFoil(){ const w = foil.getBoundingClientRect().width; if (Math.abs(w - lastFw) > 2) { lastFw = w; paintFoil(); } }
sizeFoil(); addEventListener("resize", sizeFoil);
if (document.fonts && document.fonts.ready) document.fonts.ready.then(() => { lastFw = 0; sizeFoil(); });

/* our moments: a stack of prints you swipe through */
const PH = FMI.gallery([["walk", "Our temple walks", "Nikhil and Shreya walking hand in hand along a sunlit temple corridor"], ["close", "Forehead to forehead", "Nikhil and Shreya forehead to forehead, smiling, eyes closed"], ["waterfront", "Ice cream at sunset", "Nikhil and Shreya sharing ice cream on a waterfront at sunset"], ["traditional", "Jasmine for her hair", "Shreya tucking jasmine into her braid while Nikhil holds a plate of flowers"]]);
const stack = $("stack"), dots = $("dots");
let order = PH.map((_, i) => i), busy = false;
const ROT = [-2.5, 3, -4, 2];
stack.innerHTML = PH.map((p, i) => '<figure class="card" data-i="' + i + '" style="margin:0"><img src="' + p[0] + '" alt="' + p[2] + '" width="760" height="950" loading="lazy" draggable="false"><p>' + p[1] + '</p></figure>').join("");
dots.innerHTML = PH.map(() => "<i></i>").join("");
const cards = [...stack.children];
function arrange(){
  order.forEach((ci, k) => { const c = cards[ci]; c.style.zIndex = PH.length - k; c.style.setProperty("--r", (k === 0 ? 0 : ROT[(ci + k) % 4]) + "deg"); c.style.transform = ""; c.style.transition = "transform .45s cubic-bezier(.2,.8,.2,1)"; c.setAttribute("aria-hidden", k === 0 ? "false" : "true"); });
  [...dots.children].forEach((d, i) => d.classList.toggle("on", i === order[0]));
}
arrange();
function flick(dir){
  if (busy) return; busy = true;
  const top = cards[order[0]];
  top.style.transition = "transform .42s cubic-bezier(.4,.1,.6,1)";
  top.style.transform = "translate(" + dir * 130 + "%," + (-6) + "%) rotate(" + dir * 18 + "deg)";
  chime(1318.5, .02, 0, [[1, 1, .3]]);
  setTimeout(() => { order.push(order.shift()); top.style.transition = "none"; top.style.zIndex = 0; top.style.transform = "translate(" + dir * 130 + "%,-6%) rotate(" + dir * 18 + "deg)"; void top.offsetWidth; arrange(); busy = false; }, 420);
}
function back(){
  if (busy) return; busy = true;
  order.unshift(order.pop()); const c = cards[order[0]];
  c.style.transition = "none"; c.style.zIndex = PH.length + 1; c.style.transform = "translate(-130%,-6%) rotate(-18deg)"; void c.offsetWidth;
  arrange(); setTimeout(() => busy = false, 450);
}
$("st-next").addEventListener("click", () => flick(1));
$("st-prev").addEventListener("click", back);
let drag = null;
stack.addEventListener("pointerdown", e => { const c = e.target.closest(".card"); if (!c || c !== cards[order[0]] || busy) return; drag = { c, x: e.clientX, y: e.clientY, dx: 0, lock: null, id: e.pointerId }; });
addEventListener("pointermove", e => {
  if (!drag || e.pointerId !== drag.id) return;
  const dx = e.clientX - drag.x, dy = e.clientY - drag.y;
  if (drag.lock === null && Math.abs(dx) + Math.abs(dy) > 8) { drag.lock = Math.abs(dx) > Math.abs(dy) ? "x" : "y"; if (drag.lock === "x") try { drag.c.setPointerCapture(e.pointerId); } catch (er) {} }
  if (drag.lock !== "x") return;
  drag.dx = dx; drag.c.style.transition = "none"; drag.c.style.transform = "translate(" + dx + "px," + dy * .2 + "px) rotate(" + dx * .06 + "deg)";
});
function endDrag(e){
  if (!drag || (e && e.pointerId !== drag.id)) return;
  const d = drag; drag = null;
  if (d.lock !== "x") return;
  if (Math.abs(d.dx) > Math.min(90, stack.offsetWidth * .28)) flick(d.dx > 0 ? 1 : -1);
  else { d.c.style.transition = "transform .35s cubic-bezier(.2,1.4,.4,1)"; d.c.style.transform = ""; }
}
addEventListener("pointerup", endDrag); addEventListener("pointercancel", endDrag);

/* countdown */
const cells = {}; document.querySelectorAll("#count b").forEach(b => cells[b.dataset.u] = b);
function tick(){
  let s = Math.floor((TARGET - Date.now()) / 1000);
